mapper.select:
SELECT * FROM workspace_onboarding
WHERE tenant_id = #{tenantId} AND owner_user_id = #{ownerUserId} AND request_key = #{requestKey}
LIMIT 1

SELECT * FROM workspace_onboarding
WHERE tenant_id = #{tenantId} AND workspace_id = #{workspaceId} AND owner_user_id = #{ownerUserId}
ORDER BY id DESC LIMIT 50

SELECT * FROM workspace_onboarding_step
WHERE tenant_id = #{tenantId} AND onboarding_id = #{onboardingId}
ORDER BY step_order ASC, id ASC

mapper.update:
UPDATE workspace_onboarding_step
SET status = #{status}, reason = #{reason}, evidence = #{evidence}, version = version + 1
WHERE id = #{id} AND tenant_id = #{tenantId}

mapper.select:
SELECT * FROM harness_snapshot
WHERE tenant_id = #{tenantId} AND onboarding_id = #{onboardingId} AND snapshot_type = #{snapshotType}
ORDER BY id DESC LIMIT 1

mapper.update:
UPDATE harness_snapshot SET consumed_at = CURRENT_TIMESTAMP
WHERE id = #{id} AND tenant_id = #{tenantId} AND content_sha256 = #{contentSha256}
  AND consumed_at IS NULL AND expires_at > CURRENT_TIMESTAMP

mapper.select:
SELECT * FROM harness_run
WHERE tenant_id = #{tenantId} AND onboarding_id = #{onboardingId} AND run_type = #{runType}
ORDER BY id DESC LIMIT #{limit}

mapper.update:
UPDATE harness_run
SET status = #{status}, result_json = #{resultJson}, failure_json = #{failureJson}, version = version + 1
WHERE id = #{id} AND tenant_id = #{tenantId}

mapper.select:
SELECT s.* FROM harness_run_step s
JOIN harness_run r ON r.id = s.run_id AND r.tenant_id = s.tenant_id
WHERE s.tenant_id = #{tenantId} AND r.onboarding_id = #{onboardingId} AND r.run_type = #{runType}
  AND r.snapshot_id = #{snapshotId}
  AND s.object_key = #{objectKey} AND s.status = 'SUCCEEDED'
ORDER BY s.id DESC LIMIT 1

mapper.update:
UPDATE harness_run_step
SET status = #{status}, object_id = #{objectId}, error_message = #{errorMessage}
WHERE id = #{id} AND tenant_id = #{tenantId}
